from datetime import time

WORK_START = time(9, 0)
WORK_END = time(17, 0)
DURATION_MIN = 30
DAYS = ["Monday", "Tuesday", "Wednesday"]
PARTICIPANTS = ["Joshua", "Joyce"]

def ptime(s):
    h, m = s.split(":")
    return time(int(h), int(m))

def add_minutes(t, minutes):
    total = t.hour * 60 + t.minute + minutes
    return time(total // 60, total % 60)

def fmt(t):
    return f"{t.hour:02d}:{t.minute:02d}"

MEETINGS = {
    "Joshua": {
        "Monday": [("15:00", "15:30")],
        "Tuesday": [("11:30", "12:00"), ("13:00", "13:30"), ("14:30", "15:00")],
        "Wednesday": []
    },
    "Joyce": {
        "Monday": [("09:00", "09:30"), ("10:00", "11:00"), ("11:30", "12:30"), ("13:00", "15:00"), ("15:30", "17:00")],
        "Tuesday": [("09:00", "17:00")],
        "Wednesday": [("09:00", "09:30"), ("10:00", "11:00"), ("12:30", "15:30"), ("16:00", "16:30")]
    }
}

def is_free(person, day, start, end):
    for s, e in MEETINGS[person].get(day, []):
        bs = ptime(s)
        be = ptime(e)
        if start < be and bs < end:
            return False
    return True

def preference_ok(day, start, end):
    # Joyce would rather not meet on Monday before 12:00.
    if day == "Monday" and start < ptime("12:00"):
        return False
    return True

def solve():
    t = WORK_START
    while t < WORK_END:
        end = add_minutes(t, DURATION_MIN)
        for day in DAYS:
            if not preference_ok(day, t, end):
                continue
            if all(is_free(person, day, t, end) for person in PARTICIPANTS):
                return [day, fmt(t), fmt(end)]
        t = end
    return None

if __name__ == "__main__":
    solution = solve()
    print(solution)

